import importlib.resources as pkg
import json

import aiosqlite
from fastapi import APIRouter, HTTPException
from fastapi.responses import HTMLResponse, Response

from .config import SearchRecConfig
from .db import init_db
from .recommender import retrain, get_recommendations
from .tracker import tracker_router
from .admin import admin_router
from .items import items_router


def _asset(filename: str) -> bytes:
    return (pkg.files("searchrec") / "frontend" / filename).read_bytes()


def create_router(
    db_path: str = "./rec.db",
    *,
    config: SearchRecConfig | None = None,
    min_sessions_to_retrain: int | None = None,
    min_coclick: int | None = None,
    top_n: int | None = None,
    serve_frontend: bool = True,
    frontend_prefix: str = "",
    cors_origins: list[str] | None = None,
) -> APIRouter:
    if config is None:
        config = SearchRecConfig(db_path=db_path)

    if min_sessions_to_retrain is not None:
        config.min_sessions_to_retrain = min_sessions_to_retrain
    if min_coclick is not None:
        config.min_coclick = min_coclick
    if top_n is not None:
        config.top_n = top_n
    if cors_origins is not None:
        config.cors_origins = cors_origins

    config.serve_frontend  = serve_frontend
    config.frontend_prefix = frontend_prefix

    router = APIRouter()

    # DB init on startup — works with or without a host-app lifespan
    @router.on_event("startup")
    async def _startup():
        await init_db(config.db_path)

    # Sub-routers
    router.include_router(tracker_router(config))
    router.include_router(admin_router(config))
    router.include_router(items_router(config))

    # Core recommendation routes
    @router.get("/health", tags=["core"])
    async def health():
        return {"status": "ok"}

    @router.post("/api/retrain", tags=["core"])
    async def trigger_retrain():
        return await retrain(config)

    @router.get("/api/recommend/{item_id}", tags=["core"])
    async def recommend(item_id: str, limit: int = config.recommend_limit_default):
        if limit < 1 or limit > config.recommend_limit_max:
            raise HTTPException(
                status_code=400,
                detail=f"limit must be between 1 and {config.recommend_limit_max}",
            )

        recs = await get_recommendations(config.db_path, item_id, limit)
        if not recs:
            raise HTTPException(
                status_code=404,
                detail=f"No recommendations found for '{item_id}'. Run /api/retrain first.",
            )

        rec_ids      = [r["item_id"] for r in recs]
        placeholders = ",".join("?" * len(rec_ids))
        async with aiosqlite.connect(config.db_path) as db:
            db.row_factory = aiosqlite.Row
            cursor = await db.execute(
                f"SELECT item_id, name, category, price, image_url, in_stock FROM items WHERE item_id IN ({placeholders})",
                rec_ids,
            )
            item_rows = await cursor.fetchall()

        details = {r["item_id"]: dict(r) for r in item_rows}
        enriched = [
            {
                "item_id":   r["item_id"],
                "score":     r["score"],
                "name":      details.get(r["item_id"], {}).get("name", r["item_id"]),
                "category":  details.get(r["item_id"], {}).get("category", ""),
                "price":     details.get(r["item_id"], {}).get("price", 0.0),
                "image_url": details.get(r["item_id"], {}).get("image_url", ""),
                "in_stock":  bool(details.get(r["item_id"], {}).get("in_stock", 1)),
            }
            for r in recs
        ]
        return {"item_id": item_id, "recommendations": enriched}

    # Frontend routes — only registered when serve_frontend=True
    if config.serve_frontend:
        @router.get("/config.js", include_in_schema=False)
        async def config_js():
            js = f"window.REC_BASE = {json.dumps(config.frontend_prefix)};\n"
            return Response(content=js, media_type="application/javascript")

        @router.get("/", include_in_schema=False)
        async def serve_index():
            return HTMLResponse(_asset("index.html"))

        @router.get("/admin", include_in_schema=False)
        async def serve_admin():
            return HTMLResponse(_asset("admin.html"))

        @router.get("/style.css", include_in_schema=False)
        async def serve_css():
            return Response(_asset("style.css"), media_type="text/css")

        @router.get("/tracker.js", include_in_schema=False)
        async def serve_tracker_js():
            return Response(_asset("tracker.js"), media_type="application/javascript")

    return router
